CREATE TABLE IF NOT EXISTS unidades (esn TEXT PRIMARY KEY, alias TEXT, vacio_actual INTEGER DEFAULT 34355, lleno_actual INTEGER DEFAULT 62000);
CREATE TABLE IF NOT EXISTS telemetria (id INTEGER PRIMARY KEY AUTOINCREMENT, esn TEXT, v0 REAL, v1 REAL, raw_escort INTEGER, trama TEXT, timestamp DATETIME, sync INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS calibracion_escort (id INTEGER PRIMARY KEY AUTOINCREMENT, esn TEXT, corriente_actual INTEGER, corriente_esperada INTEGER DEFAULT 62000, vacio INTEGER DEFAULT 34355, lleno_calculado INTEGER, lleno_real INTEGER DEFAULT 62000);
